const validPathnames = new Set<string>(collectedLinks.keys());
// Maps a pathname that is valid because of non-strict route matching to the
// pathname that was actually collected for the target page. This is needed
// to resolve anchors in a trailing-slash-insensitive way.
const pathnameAliases = new Map<string, string>();
const remainingRoutes: RouteConfig[] = [];
for (
  let routeIndex = 0;
  routeIndex < filteredRoutes.length;
  routeIndex += 1
) {
  const route = filteredRoutes[routeIndex]!;
  if (route.exact) {
    if (validPathnames.has(route.path)) {
      if (!route.strict) {
        const routePathnames = [
          addTrailingSlash(route.path),
          removeTrailingSlash(route.path),
        ];
        routePathnames.forEach((routePathname) => {
          validPathnames.add(routePathname);
          pathnameAliases.set(routePathname, route.path);
        });
      }
    } else {
      remainingRoutes.push(route);
    }
  } else {
    remainingRoutes.push(route);
  }
}

function findCollectedPathname(pathname: string): string | undefined {
  const pathnameVariants = [
    pathname,
    addTrailingSlash(pathname),
    removeTrailingSlash(pathname),
  ];
  for (
    let variantIndex = 0;
    variantIndex < pathnameVariants.length;
    variantIndex += 1
  ) {
    const variant = pathnameVariants[variantIndex]!;
    const decodedVariant = decodeURI(variant);
    if (collectedLinks.has(variant)) {
      return variant;
    }
    if (collectedLinks.has(decodedVariant)) {
      return decodedVariant;
    }
  }
  return undefined;
}

